function Status({ children }) { return <span className={`cw-status cw-status-${children.toLowerCase()}`}>{children}</span> }
function PostDialog({ mode, post, close, remove }) {
  const dialog = useRef(null)
  useEffect(() => {
    const element = dialog.current
    element.showModal()
    return () => element.close()
  }, [])
  return <dialog className="cw-post-dialog" ref={dialog} aria-labelledby="cw-dialog-title" onCancel={event => { event.preventDefault(); close() }} onClick={event => { if (event.target === event.currentTarget) { const bounds = event.currentTarget.getBoundingClientRect(); if (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom) close() } }}><header><h2 id="cw-dialog-title">{mode === 'delete' ? 'Delete this sample post?' : 'Post preview'}</h2><button aria-label="Close dialog" onClick={close}><Icon name="close" size={20} /></button></header>{mode === 'delete' ? <><p><strong>{post.title}</strong> will be removed from this preview session. No live post is affected.</p><footer><button className="cw-secondary" onClick={close}>Cancel</button><button className="cw-delete-button" onClick={remove}>Delete sample post</button></footer></> : <><img src={post.image} alt="" /><Status>{post.status}</Status><h3>{post.title}</h3><p>{post.description || 'No description added yet.'}</p><small>Sample post · this preview does not publish content.</small><footer><button className="cw-secondary" onClick={close}>Close preview</button></footer></>}</dialog>
}
