function PerformanceChart({ days }) {
  const [active, setActive] = useState(null)
  const data = demoPerformance[days]
  const max = 1200
  const point = (value,index) => [52 + index * 650 / (data.views.length - 1), 238 - value / max * 206]
  const curve = values => values.map((value,index) => { const [x,y]=point(value,index); if (!index) return `M ${x} ${y}`; const [px,py]=point(values[index-1],index-1); const middle=(px+x)/2; return `C ${middle} ${py}, ${middle} ${y}, ${x} ${y}` }).join(' ')
  const end = new Date('2026-11-10T12:00:00+05:30')
  const dateLabel = index => { const date=new Date(end); date.setDate(date.getDate()-days+1+Math.round(index*(days-1)/(data.views.length-1))); return date.toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Asia/Kolkata'}) }
  return <div className="ci-live-chart"><svg viewBox="0 0 730 282" role="img" aria-label={`Demo post views and visitors over ${days} days`}><title>Content performance · demonstration data</title>{[0,300,600,900,1200].map(value => <g key={value}><line x1="52" x2="702" y1={238-value/max*206} y2={238-value/max*206} stroke="#f0eaf5" strokeWidth="1" /><text x="38" y={242-value/max*206} textAnchor="end" fill="#b19dbf" fontSize="10">{value===1200?'1.2k':value}</text></g>)}<path d={curve(data.visitors)} fill="none" stroke="#c7a6df" strokeWidth="2.3" /><path d={curve(data.views)} fill="none" stroke="#8756b1" strokeWidth="2.5" />{[0,Math.floor((data.views.length-1)/3),Math.floor((data.views.length-1)*2/3),data.views.length-1].map(index => <text key={index} x={point(0,index)[0]} y="269" textAnchor="middle" fill="#aa94b8" fontSize="10">{dateLabel(index)}</text>)}{active!==null && <line x1={point(0,active)[0]} x2={point(0,active)[0]} y1="26" y2="238" stroke="#cdb8df" strokeDasharray="4 4" />}{data.views.map((value,index) => <circle key={index} cx={point(value,index)[0]} cy={point(value,index)[1]} r={active===index ? 5 : 9} fill={active===index?'#8756b1':'transparent'} stroke={active===index?'#fff':'none'} strokeWidth="3" tabIndex="0" role="button" aria-label={`${dateLabel(index)}: ${value} views, ${data.visitors[index]} visitors`} onMouseEnter={() => setActive(index)} onMouseLeave={() => setActive(null)} onFocus={() => setActive(index)} onBlur={() => setActive(null)} />)}</svg><div className="ci-chart-tooltip" aria-live="polite">{active!==null ? `${dateLabel(active)} · ${data.views[active]} views · ${data.visitors[active]} visitors` : 'Hover or focus a point to explore performance'}</div></div>
}
